(()=>{const root=()=>document.getElementById('app');let failed=false;const fatal=(reason='BOOT_FAILED')=>{if(failed)return;const host=root();if(!host||host.children.length||host.textContent?.trim())return;failed=true;host.innerHTML='<section style="min-height:100dvh;display:grid;place-items:center;padding:24px;background:#24363b;color:#eff7f5;font-family:system-ui,sans-serif"><div style="max-width:520px;text-align:center;background:#2f474d;border:1px solid #527078;border-radius:22px;padding:26px"><strong style="font-size:28px">ReMaPro Ops</strong><h1 style="font-size:18px;margin:14px 0 8px">Impossible de démarrer la console</h1><p style="color:#b9cbc8">Une ressource n’a pas pu être chargée.</p><small>Code : '+String(reason).replace(/[^A-Z0-9_.:-]/gi,'').slice(0,60)+'</small><div style="margin-top:18px"><button id="ops-retry" style="border:0;border-radius:10px;background:#d8e7e4;color:#24363b;padding:11px 16px;font-weight:800">Réessayer</button></div></div></section>';document.getElementById('ops-retry')?.addEventListener('click',()=>location.reload())};addEventListener('error',e=>setTimeout(()=>fatal(e?.error?.name||'SCRIPT_ERROR'),0));addEventListener('unhandledrejection',e=>setTimeout(()=>fatal(e?.reason?.name||'PROMISE_REJECTION'),0));setTimeout(()=>fatal('BOOT_TIMEOUT'),8000);if('serviceWorker'in navigator)addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{}))})();